<?php
session_start();require '../../config/db.php';if(!isset($_SESSION['admin_id'])){header('Location: ../../auth/login-admin.php');exit;}function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}function salvarLogoCliente($file,$clienteId){if(empty($file['name'])||!is_uploaded_file($file['tmp_name']))return null;$permitidos=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/gif'=>'gif'];$mime=mime_content_type($file['tmp_name']);if(!isset($permitidos[$mime]))throw new Exception('Envie uma logo JPG, PNG, WEBP ou GIF.');if((int)$file['size']>2*1024*1024)throw new Exception('A logo deve ter no máximo 2MB.');$dir=dirname(__DIR__,2).'/uploads/clientes/logos';if(!is_dir($dir))mkdir($dir,0755,true);$nome='cliente_'.$clienteId.'_'.time().'.'.$permitidos[$mime];if(!move_uploaded_file($file['tmp_name'],$dir.'/'.$nome))throw new Exception('Não foi possível salvar a logo.');return $nome;}$erro='';if($_SERVER['REQUEST_METHOD']==='POST'){try{$nome=trim($_POST['nome']??'');$email=trim($_POST['email']??'');$telefone=trim($_POST['telefone']??'');$senha=trim($_POST['senha']??'');if($nome===''||$email===''||$senha==='')throw new Exception('Nome, email e senha são obrigatórios.');if(strlen($senha)<6)throw new Exception('A senha deve ter no mínimo 6 caracteres.');$stmt=$pdo->prepare('SELECT id FROM clientes WHERE email=?');$stmt->execute([$email]);if($stmt->fetch())throw new Exception('Este email já está cadastrado.');$hash=password_hash($senha,PASSWORD_DEFAULT);$stmt=$pdo->prepare('INSERT INTO clientes (nome,email,telefone,senha) VALUES (?,?,?,?)');$stmt->execute([$nome,$email,$telefone,$hash]);$id=(int)$pdo->lastInsertId();$logo=salvarLogoCliente($_FILES['logo']??[],$id);if($logo){$pdo->prepare('UPDATE clientes SET logo=? WHERE id=?')->execute([$logo,$id]);}$_SESSION['success_msg']='Cliente cadastrado com sucesso.';header('Location: lista-clientes.php');exit;}catch(Throwable $e){$erro=$e->getMessage();}}?>
<!DOCTYPE html><html lang="pt-br"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Cadastrar Cliente</title><link rel="stylesheet" href="../../assets/css/helpdesk-pro.css"></head><body><div class="hd-page"><header class="hd-topbar"><div class="hd-container hd-topbar-inner"><div class="hd-brand"><div class="hd-brand-icon">➕</div><div><h1>Cadastrar cliente</h1><p>Inclua cliente, acesso e identidade visual no helpdesk.</p></div></div><div class="hd-user"><a class="hd-chip" href="dashboard.php">Dashboard</a><a class="hd-chip" href="lista-clientes.php">Clientes</a></div></div></header><main class="hd-main"><div class="hd-container"><section class="hd-card hd-card-pad"><?php if($erro):?><div class="hd-alert hd-alert-error"><?=h($erro)?></div><?php endif;?><form method="POST" enctype="multipart/form-data" class="hd-form-grid"><div class="hd-field"><label class="hd-label">Nome do cliente/empresa *</label><input class="hd-input" name="nome" required value="<?=h($_POST['nome']??'')?>"></div><div class="hd-field"><label class="hd-label">Email *</label><input class="hd-input" type="email" name="email" required value="<?=h($_POST['email']??'')?>"></div><div class="hd-field"><label class="hd-label">Telefone</label><input class="hd-input" name="telefone" value="<?=h($_POST['telefone']??'')?>"></div><div class="hd-field"><label class="hd-label">Senha inicial *</label><input class="hd-input" type="password" name="senha" minlength="6" required></div><div class="hd-field"><label class="hd-label">Logo do cliente</label><input class="hd-input" type="file" name="logo" accept="image/*" data-logo-preview="#logoPreview"><span class="hd-ticket-meta">JPG, PNG, WEBP ou GIF até 2MB.</span></div><div class="hd-field"><label class="hd-label">Prévia</label><div class="hd-logo-preview" id="logoPreview">Logo</div></div><div class="hd-field hd-field-full"><button class="hd-btn hd-btn-primary" type="submit">✅ Cadastrar cliente</button></div></form></section></div></main></div><script src="../../assets/js/helpdesk-pro.js"></script></body></html>